8	import hu.bankmonitor.payments.idempotency.IdempotentExecution;
9	import hu.bankmonitor.payments.idempotency.RequestInProgressException;
10	import jakarta.validation.Valid;
11	import jakarta.validation.constraints.NotNull;
12	import org.hibernate.validator.constraints.UUID;
13	import org.jspecify.annotations.Nullable;
14	import org.springframework.http.HttpHeaders;
15	import org.springframework.http.HttpStatus;
16	import org.springframework.http.ProblemDetail;
17	import org.springframework.http.ResponseEntity;
18	import org.springframework.web.bind.annotation.ExceptionHandler;
19	import org.springframework.web.bind.annotation.GetMapping;
20	import org.springframework.web.bind.annotation.PathVariable;
21	import org.springframework.web.bind.annotation.PostMapping;
22	import org.springframework.web.bind.annotation.RequestBody;
23	import org.springframework.web.bind.annotation.RequestHeader;
