97			if (request.sourceAccountId() == request.destinationAccountId()) {
98				throw new SelfTransferNotAllowedException(request.sourceAccountId());
99			}
100	
101			LockedAccounts locked =
102					accounts.lockForTransfer(request.sourceAccountId(), request.destinationAccountId());
103			if (locked.source().getCurrency() != locked.destination().getCurrency()) {
104				throw new CrossCurrencyTransferNotSupportedException(locked.source().getCurrency(),
105						locked.destination().getCurrency());
106			}
107	
108			Money amount = new Money(request.amountMinorUnits(), locked.source().getCurrency());
109	
110			locked.source().reserve(amount);
111	
112			Transfer requested = transfers.save(new Transfer(request.sourceAccountId(),
113					request.destinationAccountId(), amount, amount, request.requestedAt()));
114			ledger.openFor(requested);
115			return requested;
116		}
