package hu.bankmonitor.payments.fx;

import hu.bankmonitor.payments.common.Currency;

/**
 * Raised when the Exchange Rate provider did not answer, and had run out of attempts.
 *
 * <p>Distinct from every other way this port can fail, because it is the only one that
 * means <em>try again later</em>. A provider that refuses a request outright — an unquoted
 * currency, a malformed query — has given a deterministic answer, and asking it again
 * produces the same one; those surface as {@link IllegalStateException} and are defects in
 * this application rather than outages at the other end. A caller that could not tell the
 * two apart would invite its own client to retry something that will never succeed.
 *
 * <p>Carries the pair because a failing provider is usually failing for one of them, and
 * the attempt count because "we asked three times" is the difference between a blip this
 * application already absorbed and one it never had a chance against. Which status the
 * refusal becomes, under which problem type URN and with what {@code Retry-After}, belongs
 * to the endpoint in ticket 26.
 *
 * <p>The count is what the configured policy allows, not a tally of what happened: Spring
 * discards the object that knew the real number before this application sees the failure.
 * The two agree whenever the policy is actually running, which is the thing
 * {@code ExchangeRateClientGivesUpOnASilentProviderTest} exists to hold.
 */
public class ExchangeRateUnavailableException extends RuntimeException {

	private final Currency base;

	private final Currency quote;

	private final int attempts;

	public ExchangeRateUnavailableException(Currency base, Currency quote, int attempts, Throwable cause) {
		super("no %s/%s rate after %d attempts".formatted(base, quote, attempts), cause);
		this.base = base;
		this.quote = quote;
		this.attempts = attempts;
	}

	public Currency getBase() {
		return base;
	}

	public Currency getQuote() {
		return quote;
	}

	public int getAttempts() {
		return attempts;
	}
}

package hu.bankmonitor.payments.fx;

import hu.bankmonitor.payments.common.Currency;
import org.springframework.resilience.annotation.Retryable;
import org.springframework.stereotype.Component;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.RestClient;

/**
 * One request to the Exchange Rate provider, asked again when the answer was the provider
 * having a bad moment.
 *
 * <p>This is the whole of the retry policy, and it is a separate bean from
 * {@link HttpExchangeRateProvider} for a reason that is structural rather than tidy:
 * {@code @Retryable} is proxy-based, so a call this class made to its own method would
 * bypass the proxy and never retry. The interception has to happen on a boundary between
 * two beans, which puts the mapping of the provider's failures onto ours in the caller.
 *
 * <p>{@code includes} names the two failures worth asking again about — the provider
 * answering {@code 5xx}, and the connection timing out or breaking, which reaches us as
 * {@link ResourceAccessException}. Everything else, {@code 4xx} above all, propagates from
 * the first attempt. A deterministic refusal repeated three times is three refusals and
 * one lie about how hard we tried.
 *
 * <p>The reasoning, and the alternatives rejected, are in
 * {@code docs/design-decisions/25-exchange-rate-client.md}.
 */
@Component
class RetriedQuotes {

	/**
	 * The wire contract of whoever {@code payments.fx.base-url} points at. Deliberately not
	 * shared with the stand-in that also serves this path: that would make the client's URL
	 * a fact about our own test double.
	 */
	private static final String RATES_PATH = "/fx/rates";

	private final RestClient provider;

	RetriedQuotes(RestClient exchangeRateClient) {
		this.provider = exchangeRateClient;
	}

	/**
	 * @throws HttpServerErrorException if the provider failed every attempt
	 * @throws ResourceAccessException if the connection failed or timed out every attempt
	 * @throws org.springframework.web.client.HttpClientErrorException if the provider
	 *         refused the request, on the first attempt and without a second
	 */
	@Retryable(
			includes = { HttpServerErrorException.class, ResourceAccessException.class },
			maxRetriesString = ExchangeRateSettings.MAX_RETRIES_PLACEHOLDER,
			delayString = ExchangeRateSettings.RETRY_DELAY_PLACEHOLDER,
			multiplier = 2.0)
	ProviderQuote forPair(Currency base, Currency quote) {
		return provider.get()
				.uri(builder -> builder.path(RATES_PATH)
						.queryParam("base", base.name())
						.queryParam("quote", quote.name())
						.build())
				.retrieve()
				.body(ProviderQuote.class);
	}
}

package hu.bankmonitor.payments.transfers;

import java.time.Instant;
import java.util.Objects;

/**
 * What a caller has to say to request a Transfer: the two Accounts, how much to move, and
 * when it was asked for.
 *
 * <p><b>The amount is a bare count of Minor Units and not {@link
 * hu.bankmonitor.payments.common.Money}</b>, which is the one place in this context where a
 * number without a Currency is the honest shape. The Currency of a Transfer is the source
 * Account's, and the source Account is only read under the row lock design decision 6
 * requires — so a caller could only name a Currency here by reading the Account first,
 * outside the lock, which is the read that design decision exists to forbid. The count
 * becomes Money inside {@link FundsReservation}, at the first moment there is an Account to
 * denominate it.
 *
 * <p>Design decision 15 locks the Exchange Rate at request time, so ticket 26 will bring a
 * second amount for the credited side. Until then both sides of a Transfer are the same
 * figure and this carries it once.
 */
public record ReservationRequest(
		long sourceAccountId,
		long destinationAccountId,
		long amountMinorUnits,
		Instant requestedAt) {

	public ReservationRequest {
		Objects.requireNonNull(requestedAt, "a transfer is requested at a time");
	}
}

