package hu.bankmonitor.payments.idempotency;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;

import java.util.Optional;
import java.util.function.Supplier;

/**
 * {@link IdempotentExecution} over the claim mechanics of {@link IdempotencyClaims}: the
 * three phases of design decision 4, with design decision 5's four answers decided between
 * the first and the last.
 *
 * <p>The order below is the whole of the guarantee, and no two steps are interchangeable:
 *
 * <ol>
 * <li>claim the key, where the unique constraint — not a preceding read — is what
 * discovers a duplicate;
 * <li>if it was refused, read the claim that beat this one and answer from it, without
 * ever reaching the operation;
 * <li>otherwise run the operation and close the claim, in one transaction that commits
 * both or neither.
 * </ol>
 *
 * <p>Phase two of design decision 4 — resolving anything slow with no locks held — has no
 * slot here, because there is nothing to resolve until ticket 26 fetches an Exchange Rate.
 * It is not a hole in the ordering: duplicate resolution already happens above everything,
 * so a duplicate never reaches whatever ends up between the claim and the transaction.
 *
 * <p>Package-private, like everything else in this slice. What another slice may hold is
 * the port.
 */
@Service
class ClaimedExecution implements IdempotentExecution {

	private final IdempotencyClaims claims;

	private final IdempotencyRecordRepository records;

	private final ObjectMapper json;

	/**
	 * The phase-three transaction, opened by hand rather than declared with
	 * {@code @Transactional}, for two reasons that both come from ticket 16.
	 *
	 * <p>An annotation on a method of this class called from another method of this class
	 * is not proxied at all, so the transaction would silently not exist and
	 * {@link IdempotencyClaims#markSucceeded}'s {@code MANDATORY} propagation would be the
	 * only thing to say so. And the release of a failed claim has to happen <em>after</em>
	 * this transaction has ended rather than inside it, which is a line of code with a
	 * template and an invisible property of the method boundary with an annotation.
	 */
	private final TransactionTemplate transaction;

	ClaimedExecution(IdempotencyClaims claims, IdempotencyRecordRepository records, ObjectMapper json,
			PlatformTransactionManager transactionManager) {
		this.claims = claims;
		this.records = records;
		this.json = json;
		this.transaction = new TransactionTemplate(transactionManager);
	}

	@Override
	public <T> T executeOnce(String idempotencyKey, String payloadHash, Class<T> responseType,
			Supplier<T> operation) {
		try {
			claims.claim(idempotencyKey, payloadHash);
		}
		catch (DataIntegrityViolationException duplicate) {
			Optional<T> alreadyAnswered =
					replayOrReclaim(idempotencyKey, payloadHash, responseType, duplicate);
			if (alreadyAnswered.isPresent()) {
				return alreadyAnswered.get();
			}
		}
		return runUnderTheClaim(idempotencyKey, operation);
	}

	/**
	 * Design decision 5's table, read off the claim that already holds the key.
	 *
	 * <p>An empty result means this caller now holds the key and should go on to execute,
	 * which is the {@code FAILED} row and the only one that is neither an answer nor a
	 * refusal. Every other row either returns the first request's response or throws.
	 *
	 * <p><b>An absent row rethrows the violation rather than assuming this was the key's.</b>
	 * It is the guard that keeps the duplicate path from swallowing an insert some other
	 * constraint refused — a payload hash of the wrong length, say — which would otherwise
	 * surface as a {@code 409} naming a claim that does not exist. Matching on the
	 * constraint's name would answer the same question and would tie this class to a string
	 * H2 and PostgreSQL format differently.
	 *
	 * <p>The payload is compared before the status is looked at, which is what makes the
	 * mismatch one row of that table rather than three. A repeat carrying a different
	 * payload is a client mistake whatever the first request got to — and answering it from
	 * a {@code SUCCEEDED} claim would hand a client the response to a request it never made.
	 */
	private <T> Optional<T> replayOrReclaim(String idempotencyKey, String payloadHash,
			Class<T> responseType, DataIntegrityViolationException violation) {
		IdempotencyRecord claimed = records.findByIdempotencyKey(idempotencyKey)
				.orElseThrow(() -> violation);

		if (!claimed.getPayloadHash().equals(payloadHash)) {
			throw new IdempotencyKeyReusedException(idempotencyKey);
		}

		return switch (claimed.getStatus()) {
			case IN_PROGRESS -> throw new RequestInProgressException(idempotencyKey);
			case SUCCEEDED -> Optional.of(json.readValue(claimed.getResponseBody(), responseType));
			case FAILED -> reclaimed(idempotencyKey);
		};
	}

	/**
	 * The loser of a race for a failed key is told the request is in progress, and by then it
	 * is: the winner is holding the claim it just took. Ticket 18 provokes this branch, which
	 * no single-threaded test can reach.
	 */
	private <T> Optional<T> reclaimed(String idempotencyKey) {
		if (!claims.reclaimFailed(idempotencyKey)) {
			throw new RequestInProgressException(idempotencyKey);
		}
		return Optional.empty();
	}

	/**
	 * Phase three: the operation and the flip to {@code SUCCEEDED} in one transaction, and
	 * the release of the claim strictly outside it.
	 *
	 * <p>The {@code catch} sits outside the template deliberately. Releasing a claim commits
	 * on its own so that it survives the rollback it reports, and a new transaction cannot
	 * see the locks the failing one is still holding — so releasing from inside would wait on
	 * a row lock only the transaction it is running within can release. Ticket 16 measured it
	 * at a two-second timeout ending with the row stranded at {@code IN_PROGRESS}, which is
	 * the one state this whole path exists to prevent.
	 *
	 * <p>It catches {@link Throwable} rather than {@link RuntimeException} for that same
	 * reason. An {@link Error} is not this class's to handle and is rethrown untouched, but
	 * letting one past the release would strand the key exactly as the timeout did, and
	 * nothing sweeps stranded keys: a retry of a recoverable failure is the whole promise
	 * this slice makes, and it must not depend on which unchecked throwable arrived.
	 */
	private <T> T runUnderTheClaim(String idempotencyKey, Supplier<T> operation) {
		try {
			return transaction.execute(status -> {
				T answer = operation.get();
				claims.markSucceeded(idempotencyKey, json.writeValueAsString(answer));
				return answer;
			});
		}
		catch (Throwable failure) {
			release(idempotencyKey, failure);
			throw failure;
		}
	}

	/**
	 * A claim that cannot be released is reported attached to the failure that was being
	 * released for, never instead of it: the caller asked about the operation, and a key
	 * stranded by bookkeeping is a second fact rather than a replacement for the first.
	 */
	private void release(String idempotencyKey, Throwable failure) {
		try {
			claims.markFailed(idempotencyKey);
		}
		catch (RuntimeException unrecorded) {
			failure.addSuppressed(unrecorded);
		}
	}
}

package hu.bankmonitor.payments.common;

import java.net.URI;

/**
 * Every problem type this API can answer with, and the sole thing a client branches on.
 *
 * <p>Not the status code, and not a second {@code code} field beside this one: two
 * discriminators drift, and eventually one of them lies. {@link #REQUEST_IN_PROGRESS} and
 * {@link #IDEMPOTENCY_KEY_REUSED} are the case that makes the rule concrete — the same
 * {@code 409}, opposite advice about retrying.
 *
 * <p>The vocabulary lives here, in the package every slice depends on, so that the
 * backend and the frontend's generated types agree from one place. A slice that starts
 * refusing something new adds its constant here rather than writing a URN at the throw
 * site.
 */
public enum ProblemType {

	/** The request was readable, and what it said was not acceptable. Carries per-field detail. */
	VALIDATION_FAILED("validation-failed"),

	/** The request body could not be read at all — malformed JSON. */
	MALFORMED_REQUEST("malformed-request"),

	UNSUPPORTED_MEDIA_TYPE("unsupported-media-type"),

	METHOD_NOT_ALLOWED("method-not-allowed"),

	NOT_FOUND("not-found"),

	/** Both sides of a Transfer named the same Account. */
	SELF_TRANSFER("self-transfer"),

	/** A Transfer named an Account that does not exist. Carries the ID that was wrong. */
	UNKNOWN_ACCOUNT("unknown-account"),

	/** The source Account's Available Balance does not cover the Transfer. Carries both figures. */
	INSUFFICIENT_FUNDS("insufficient-funds"),

	/**
	 * The two Accounts are denominated differently, which this service cannot convert
	 * between yet. Names a capability rather than a rule, because ticket 26 deletes it
	 * rather than reinterpreting it.
	 */
	CROSS_CURRENCY_UNSUPPORTED("cross-currency-unsupported"),

	/** The same idempotency key is being processed right now. Retryable, and says when. */
	REQUEST_IN_PROGRESS("request-in-progress"),

	/** The same idempotency key was used for a different payload. Retrying can never succeed. */
	IDEMPOTENCY_KEY_REUSED("idempotency-key-reused"),

	/** The exchange rate provider failed every attempt. Retryable, and says when. */
	FX_PROVIDER_UNAVAILABLE("fx-provider-unavailable"),

	/**
	 * The caller's fault, and this API does not name it more precisely — a {@code 406},
	 * say. The honest answer for a client error nothing above describes: a URN that
	 * claimed more than is known would be the discriminator lying, and a client shows an
	 * unrecognised type generically anyway.
	 */
	CLIENT_ERROR("client-error"),

	/** Something broke on this side. Deliberately says nothing else. */
	INTERNAL_ERROR("internal-error");

	private static final String NAMESPACE = "urn:problem:";

	private final URI uri;

	ProblemType(String name) {
		this.uri = URI.create(NAMESPACE + name);
	}

	/** The value of the problem document's {@code type} member. */
	public URI uri() {
		return uri;
	}

	/** The same value as text, for comparing against a document that has been parsed. */
	public String urn() {
		return uri.toString();
	}
}

package hu.bankmonitor.payments.accounts;

import com.tngtech.archunit.base.DescribedPredicate;
import com.tngtech.archunit.core.domain.Dependency;
import com.tngtech.archunit.core.domain.JavaClass;
import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import hu.bankmonitor.testsupport.boundaryviolations.lockedpath.LockHolder;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import static com.tngtech.archunit.core.domain.JavaClass.Predicates.resideInAnyPackage;
import static org.assertj.core.api.Assertions.assertThat;

/**
 * The constraint that makes pessimistic locking affordable: a transaction holding row
 * locks waits on nothing slower than the database.
 *
 * <p>Design decision 4 fetches the Exchange Rate in a phase of its own precisely so that
 * it is not inside these locks, and design decision 6 says that placement is what makes
 * the whole locking design viable. The half of it that lives in {@code transfers} — that
 * the rate is fetched with no transaction open — is ticket 26's to assert. What is
 * assertable here is the other half: that the operation holding the locks cannot reach
 * anything but the database, however far down its call graph the reach would be.
 *
 * <p>The reachable set is walked here rather than left to ArchUnit's
 * {@code transitivelyDependOnClassesThat}, which follows dependencies into the JDK as
 * well and so finds a path from every class to {@code java.net.URL} by way of
 * {@code java.lang.Class}. Walking only the application's own classes is both the
 * question worth asking and the only one with a useful answer: a call to a provider is a
 * class of ours that holds the client.
 *
 * <p>Two limits of the technique, stated because neither is visible from a green tick:
 *
 * <ul>
 * <li><b>The walk stops at an interface.</b> A dependency on one yields its declarations,
 * never its implementations, so a port whose HTTP implementation lives elsewhere is
 * invisible to the hop that would find it. What covers that case is
 * {@link #IO_BEYOND_THE_DATABASE} naming the {@code fx} and {@code mockfx} <em>packages</em>
 * rather than any client type: the port itself is the forbidden dependency, whichever
 * class implements it. A port added outside those packages would slip through, which is
 * the argument for keeping provider slices where §30 puts them.
 * <li><b>{@link #LOCK_HOLDERS} is a list, not a query.</b> Nothing derives it, so a future
 * transactional method that takes these locks is covered only once it is named here —
 * see {@link #theLockHolderReachesNothingButTheDatabase}.
 * </ul>
 */
class LockedPathTouchesOnlyTheDatabaseTest {

	/**
	 * Sockets, files, the servlet API, Spring's HTTP packages, and the two slices that put
	 * a provider behind them — ticket 25 makes the {@code fx} call a real one, and no
	 * amount of it belongs under a lock.
	 *
	 * <p>Deliberately a list of packages rather than an attempt at every HTTP client in
	 * existence: naming Apache HttpClient and OkHttp would suggest the list is exhaustive
	 * when the next dependency added to the {@code pom} would make it false again. What is
	 * exhaustive is the {@code fx} and {@code mockfx} entries — a provider call in this
	 * application lives in one of those two by §30, whatever it is built out of.
	 */
	private static final DescribedPredicate<JavaClass> IO_BEYOND_THE_DATABASE = resideInAnyPackage(
			"java.net..",
			"java.io..",
			"java.nio.file..",
			"jakarta.servlet..",
			"org.springframework.web..",
			"org.springframework.http..",
			"hu.bankmonitor.payments.fx..",
			"hu.bankmonitor.payments.mockfx..");

	/**
	 * Every operation that takes these row locks: the one that exports them, and the two that
	 * open a transaction the locks are held in — the reservation that requests a Transfer and
	 * the Verdict that ends one.
	 *
	 * <p>Deliberately not "everything that calls {@link AccountLocking}". The caller is
	 * where the transaction is opened, so widening this to callers looks stricter and is
	 * wrong: ticket 26 gives {@code FundsReservation} an Exchange Rate port to call in the
	 * phase <em>before</em> the transaction, which is precisely what design decision 4 asks
	 * for, and this rule cannot tell the two phases apart. When that arrives the entry below
	 * has to come out, and ticket 26 asserts the phase ordering the other way, in
	 * {@code transfers}.
	 *
	 * <p>Class names rather than {@code Class} literals, because {@code FundsReservation} is
	 * package-private in {@code transfers} by §30 and so cannot be named from this package —
	 * which is the boundary working, not an obstacle to route around by widening its
	 * visibility for a test. A name that matches nothing fails loudly in
	 * {@link JavaClasses#get(String)} rather than quietly asserting over an empty set.
	 */
	private static final List<String> LOCK_HOLDERS = List.of(
			AccountLocking.class.getName(),
			"hu.bankmonitor.payments.transfers.FundsReservation",
			"hu.bankmonitor.payments.transfers.VerdictRecording");

	@Test
	@DisplayName("the operation that holds the locks reaches nothing but the database")
	void theLockHolderReachesNothingButTheDatabase() {
		JavaClasses productionClasses = new ClassFileImporter()
				.withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
				.importPackages("hu.bankmonitor.payments");

		assertThat(LOCK_HOLDERS)
				.allSatisfy(lockHolder -> assertThat(ioReachableFrom(lockHolder, productionClasses))
						.as("a transaction holding account locks must never wait on a slow provider")
						.isEmpty());
	}

	/**
	 * The shape the mistake actually takes, and the reason the walk follows hops at all: a
	 * check reading only direct dependencies would pass {@link LockHolder}, which holds no
	 * client itself and calls one that does.
	 *
	 * <p>Be clear about what this does and does not establish. It proves the <em>walk</em>
	 * is falsifiable — that the search above returns a finding when a finding exists —
	 * which is what stops the green tick above from being the green tick of a rule that
	 * stopped matching. It does not prove the production invocation is falsifiable, because
	 * it runs over a different import scope from a different origin. Nothing short of
	 * putting a client in the real locked path would prove that, and the cost of doing so
	 * permanently is a class in {@code accounts} that exists only to be wrong.
	 *
	 * <p>The count of entries is not pinned: one call through {@code RestClient}'s fluent
	 * builder depends on each interface in the chain, so the list grows and shrinks with a
	 * Spring upgrade. What the rule claims is that the reach is found and blamed on the
	 * class that made it.
	 */
	@Test
	@DisplayName("a lock holder that reaches an HTTP client one hop down is reported")
	void detectsIoOneHopBelowTheLockHolder() {
		JavaClasses violation = new ClassFileImporter()
				.importPackages("hu.bankmonitor.testsupport.boundaryviolations.lockedpath");

		assertThat(ioReachableFrom(LockHolder.class.getName(), violation))
				.as("the reach is real, and it is attributed to the class one hop down")
				.contains("ExchangeRateLookup depends on org.springframework.web.client.RestClient")
				.allSatisfy(reach -> assertThat(reach).startsWith("ExchangeRateLookup depends on"));
	}

	/**
	 * Every forbidden dependency of every class the lock holder can reach, as text a
	 * failure message can name the culprit with.
	 */
	private static List<String> ioReachableFrom(String lockHolder, JavaClasses ourClasses) {
		return reachableFrom(ourClasses.get(lockHolder), ourClasses).stream()
				.flatMap(onThePath -> onThePath.getDirectDependenciesFromSelf().stream())
				.filter(dependency -> IO_BEYOND_THE_DATABASE.test(targetOf(dependency)))
				.map(dependency -> dependency.getOriginClass().getSimpleName()
						+ " depends on " + targetOf(dependency).getFullName())
				.distinct()
				.toList();
	}

	/** Breadth-first over {@code ourClasses} only, so the walk stops at the framework. */
	private static Set<JavaClass> reachableFrom(JavaClass origin, JavaClasses ourClasses) {
		Set<JavaClass> reached = new LinkedHashSet<>();
		Deque<JavaClass> frontier = new ArrayDeque<>(List.of(origin));
		while (!frontier.isEmpty()) {
			JavaClass next = frontier.removeFirst();
			if (!reached.add(next)) {
				continue;
			}
			next.getDirectDependenciesFromSelf().stream()
					.map(LockedPathTouchesOnlyTheDatabaseTest::targetOf)
					.filter(target -> ourClasses.contain(target.getName()))
					.forEach(frontier::addLast);
		}
		return reached;
	}

	/** An array dependency reports the array type, and its package is the element's. */
	private static JavaClass targetOf(Dependency dependency) {
		return dependency.getTargetClass().getBaseComponentType();
	}
}

