1	package hu.bankmonitor.payments.fx;
2	
3	import org.springframework.boot.context.properties.EnableConfigurationProperties;
4	import org.springframework.context.annotation.Bean;
5	import org.springframework.context.annotation.Configuration;
6	import org.springframework.core.task.VirtualThreadTaskExecutor;
7	import org.springframework.http.client.ClientHttpRequestFactory;
8	import org.springframework.http.client.JdkClientHttpRequestFactory;
9	import org.springframework.resilience.annotation.EnableResilientMethods;
10	import org.springframework.web.client.RestClient;
11	
12	import java.net.http.HttpClient;
13	
14	/**
15	 * The one client in this application that talks to somebody else, built from the settings
16	 * that say where it talks and the two timeouts that keep it from talking forever.
17	 *
18	 * <p>{@code @EnableResilientMethods} is application-wide — it registers a bean
19	 * post-processor, not a slice-local one — but it is declared here rather than in the root
20	 * package because the only retryable method in the system is a few lines away, and a
21	 * second slice wanting retry should find the annotation by finding the code that already
22	 * uses it. Spring Boot does not auto-configure it; without this line {@code @Retryable}
23	 * is an annotation nothing reads, and the first attempt is the only attempt, silently.
24	 *
25	 * <p>The reasoning, and the alternatives rejected, are in
26	 * {@code docs/design-decisions/25-exchange-rate-client.md}.
27	 */
28	@Configuration
29	@EnableResilientMethods
30	@EnableConfigurationProperties(ExchangeRateSettings.class)
31	class ExchangeRateConfiguration {
32	
33		@Bean
34		RestClient exchangeRateClient(ExchangeRateSettings settings) {
35			return RestClient.builder()
36					.baseUrl(settings.baseUrl().toString())
37					.requestFactory(boundedByTimeouts(settings))
38					.build();
39		}
40	
41		/**
42		 * Both timeouts, on the JDK's own HTTP client.
43		 *
44		 * <p>Without them "the provider is slow" has no upper bound, and §27's failure mode
45		 * arrives: a request parks indefinitely while holding an in-progress Idempotency Key,
46		 * so an unreliable third party becomes a Transfer that can never be retried.
47		 *
48		 * <p>The connect timeout belongs to the client and the read timeout to the request
49		 * factory, because the JDK client has no read timeout of its own — Spring's factory
50		 * implements it as a watchdog over the whole response.
51		 *
52		 * <p>The executor is virtual for the same reason {@code spring.threads.virtual.enabled}
53		 * is set: under the {@code mock-fx} profile this application is its own provider, and
54		 * the JDK client's default executor is a pool of platform threads sitting in the middle
55		 * of that self-call.
56		 */
57		private static ClientHttpRequestFactory boundedByTimeouts(ExchangeRateSettings settings) {
58			HttpClient httpClient = HttpClient.newBuilder()
59					.connectTimeout(settings.connectTimeout())
60					.executor(new VirtualThreadTaskExecutor("fx-client-"))
61					.build();
62	
63			JdkClientHttpRequestFactory requests = new JdkClientHttpRequestFactory(httpClient);
64			requests.setReadTimeout(settings.readTimeout());
65			return requests;
66		}
67	}
