2	
3	import com.tngtech.archunit.core.domain.JavaClass;
4	import com.tngtech.archunit.core.domain.JavaClasses;
5	import com.tngtech.archunit.core.importer.ClassFileImporter;
6	import com.tngtech.archunit.core.importer.ImportOption;
7	import com.tngtech.archunit.lang.ArchRule;
8	import org.junit.jupiter.api.DisplayName;
9	import org.junit.jupiter.api.Nested;
10	import org.junit.jupiter.api.Test;
11	import org.springframework.data.repository.Repository;
12	import org.springframework.stereotype.Controller;
13	
14	import java.util.List;
15	
16	import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
17	import static com.tngtech.archunit.library.dependencies.SlicesRuleDefinition.slices;
18	import static org.assertj.core.api.Assertions.assertThat;
19	import static org.assertj.core.api.Assertions.assertThatThrownBy;
20	
21	/**
22	 * The module boundaries of design decision 30, as a test rather than a diagram.
23	 *
24	 * <p>Most of those boundaries need no test: Java's default access level is
25	 * package-private and the compiler enforces it, so a package-private repository is
26	 * uncallable from another slice and the build says so. What the compiler cannot see is
27	 * the shape of the graph between packages that <em>do</em> depend on each other, which is
28	 * what the two rules here cover.
29	 *
30	 * <p>Both rules allow an empty match. They are prohibitions, and a prohibition over zero
31	 * classes holds; without this ArchUnit treats "matched nothing" as a failure, which would
32	 * make the rules unwritable until the first controller lands. The cost of that permission
33	 * is that a rule could quietly stop matching anything and still pass, so
34	 * {@link RulesFailWhenViolated} checks each rule against code that breaks it.
35	 */
36	class ModuleBoundariesHoldTest {
37	
38		private static final String ROOT_PACKAGE = "hu.bankmonitor.payments";
39	
40		/**
41		 * Every package the design calls for, relative to {@link #ROOT_PACKAGE}. Not the same
42		 * list as the slices: the application class sits in the root and belongs to no slice,
43		 * and {@code transfers.checks} is folded into the {@code transfers} slice by the
44		 * matching pattern below, which is the point of making it a sub-package.
45		 */
46		private static final List<String> DOCUMENTED_PACKAGES = List.of(
47				"accounts", "transfers", "transfers.checks", "idempotency", "fx", "outbox",
48				"mockfx", "common");
49	
50		/**
51		 * Matches on role as well as on name. The suffix alone would be the whole rule in a
52		 * codebase that never drifts, but it is the naming — not the boundary — that drifts
53		 * first: an {@code AccountEndpoint} annotated {@code @RestController} is the same
54		 * mistake wearing a different name, and it is the rename that would make this rule
55		 * stop noticing.
56		 */
57		private static final ArchRule NO_CONTROLLER_REACHES_A_REPOSITORY = noClasses()
58				.that().haveSimpleNameEndingWith("Controller")
59				.or().areMetaAnnotatedWith(Controller.class)
60				.should().dependOnClassesThat().haveSimpleNameEndingWith("Repository")
61				.orShould().dependOnClassesThat().areAssignableTo(Repository.class)
62				.because("a controller holding a repository has skipped the service that owns the transaction")
63				.allowEmptyShould(true);
64	
65		private final JavaClasses productionClasses = new ClassFileImporter()
66				.withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
67				.importPackages(ROOT_PACKAGE);
68	
69		/**
70		 * A package with no types in it is invisible to everything below, so the skeleton
71		 * would be an empty assertion rather than a passing one. What puts these packages on
72		 * the classpath today is their {@code package-info}: javac compiles one to a class
73		 * file even when it carries nothing but Javadoc, which is the opposite of the usual
74		 * advice that a {@code package-info.class} needs an annotation to exist.
75		 */
76		@Test
77		@DisplayName("every package the design calls for exists")
78		void everyPackageOfTheDesignExists() {
79			assertThat(productionClasses.stream().map(JavaClass::getPackageName).distinct())
80					.containsAll(DOCUMENTED_PACKAGES.stream().map(name -> ROOT_PACKAGE + "." + name).toList());
81		}
82	
83		/**
84		 * Cycle-freedom is the machine-checkable half of "dependencies run one way". The
85		 * direction itself — {@code transfers} onto the others and never back — is a design
86		 * choice ArchUnit cannot infer, but any attempt to point one back at
87		 * {@code transfers} closes a loop and lands here.
88		 */
89		@Test
90		@DisplayName("the slices are free of cycles")
91		void theSlicesAreFreeOfCycles() {
92			slicesOf(ROOT_PACKAGE).check(productionClasses);
93		}
94	
95		@Test
96		@DisplayName("no controller reaches a repository directly")
97		void noControllerReachesARepository() {
98			NO_CONTROLLER_REACHES_A_REPOSITORY.check(productionClasses);
99		}
100	
101		private static ArchRule slicesOf(String rootPackage) {
102			return slices()
103					.matching(rootPackage + ".(*)..")
104					.should().beFreeOfCycles()
105					.allowEmptyShould(true);
106		}
107	
108		/**
109		 * The fixtures that break each rule on purpose live under
110		 * {@code testsupport.boundaryviolations}, outside the packages the rules above scan.
111		 */
112		@Nested
113		@DisplayName("the rules fail when violated")
114		class RulesFailWhenViolated {
115	
116			private static final String VIOLATIONS_PACKAGE = "hu.bankmonitor.testsupport.boundaryviolations";
117	
118			@Test
119			@DisplayName("two slices that depend on each other are reported as a cycle")
120			void detectsACycleBetweenSlices() {
121				JavaClasses cycle = importViolation("cycles");
122	
123				assertThatThrownBy(() -> slicesOf(VIOLATIONS_PACKAGE + ".cycles").check(cycle))
124						.isInstanceOf(AssertionError.class)
125						.hasMessageContaining("Cycle detected");
126			}
127	
128			@Test
129			@DisplayName("a controller holding a repository is reported, by name")
130			void detectsAControllerReachingARepositoryByName() {
131				JavaClasses leak = importViolation("layering.bysuffix");
132	
133				assertThatThrownBy(() -> NO_CONTROLLER_REACHES_A_REPOSITORY.check(leak))
134						.isInstanceOf(AssertionError.class)
135						.hasMessageContaining("LeakyController")
136						.hasMessageContaining("LeakyRepository");
137			}
138	
139			/** The half a suffix-only rule would miss, and the reason the rule is not one. */
140			@Test
141			@DisplayName("a controller holding a repository is reported, by role")
142			void detectsAControllerReachingARepositoryByRole() {
143				JavaClasses leak = importViolation("layering.byrole");
144	
145				assertThatThrownBy(() -> NO_CONTROLLER_REACHES_A_REPOSITORY.check(leak))
146						.isInstanceOf(AssertionError.class)
147						.hasMessageContaining("AccountEndpoint")
148						.hasMessageContaining("AccountStore");
149			}
150	
151			/** Without {@code DO_NOT_INCLUDE_TESTS}, which would filter out these fixtures. */
152			private static JavaClasses importViolation(String violation) {
