1	package hu.bankmonitor.payments.transfers;
2	
3	import hu.bankmonitor.payments.common.Currency;
4	import hu.bankmonitor.payments.transfers.checks.Check;
5	import hu.bankmonitor.testsupport.BootedApplicationTest;
6	import org.junit.jupiter.api.AfterEach;
7	import org.junit.jupiter.api.BeforeEach;
8	import org.springframework.beans.factory.annotation.Autowired;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	
11	import java.time.Instant;
12	import java.util.List;
13	import java.util.Map;
14	
15	/**
16	 * The Accounts, the reads and the cleanup every test of a Transfer's life shares — the
17	 * reservation that opens one and the Verdict that closes it.
18	 *
19	 * <p><b>Nothing here is transactional, and that is the point.</b> A {@code @Transactional}
20	 * test method makes every write it performs invisible to any other connection and rolls the
21	 * lot back at the end — which would leave
22	 * {@link ConcurrentReservationsHoldTheBalanceTest}'s second thread unable to see the first
23	 * thread's reservation, and every assertion in
24	 * {@link ReservedFundsReachTheTableTest} agreeing with a transaction that never committed.
25	 * Every subclass needs real commits, so the price is paying for the cleanup by hand.
26	 *
27	 * <p>The tables are emptied before each method as well as after: one in-memory H2 database is
28	 * shared by every test in the suite, whichever application context booted it, and the
29	 * assertions below count rows rather than looking only at their own.
30	 *
31	 * <p>Rows go in and come back out in SQL rather than through the entities, so what is
32	 * asserted is what reached the database — a round trip through the mapping under test would
33	 * agree with itself whatever it wrote.
34	 */
35	abstract class TransferScenario extends BootedApplicationTest {
36	
37		static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");
38	
39		@Autowired
40		FundsReservation reservation;
41	
42		@Autowired
43		VerdictRecording verdicts;
44	
45		@Autowired
46		JdbcTemplate database;
47	
48		/**
49		 * Ledger first, then Transfers, then Accounts: each table points at the one below it.
50		 * Claims come last and in any order — no foreign key reaches an Idempotency Key, which
51		 * is the point of design decision 3 putting the claim above the work rather than beside
52		 * it.
53		 *
54		 * <p>The claims are emptied here rather than by the two subclasses that request
55		 * Transfers over HTTP, because a key left behind outlives the test that made it: it is
56		 * committed by design, so the next test to use the same key would be answered by the
57		 * previous test's claim instead of making one.
58		 */
59		@BeforeEach
60		@AfterEach
61		void emptyTheLedgerTransferAccountAndClaimTables() {
62			database.update("DELETE FROM check_ledger");
63			database.update("DELETE FROM transfers");
64			database.update("DELETE FROM accounts");
65			database.update("DELETE FROM idempotency_records");
66		}
67	
68		/**
69		 * With an explicit identifier, which the identity column accepts because it is declared
70		 * {@code generated by default}. The lock order is ascending by ID, so a test about two
71		 * Accounts needs to be able to say which of them is the lower one.
72		 */
73		void openAccount(long id, long balanceMinorUnits, Currency currency) {
74			database.update("""
75					INSERT INTO accounts (id, balance_minor_units, balance_currency,
76					                      reserved_amount_minor_units, reserved_amount_currency)
77					VALUES (?, ?, ?, 0, ?)
78					""", id, balanceMinorUnits, currency.name(), currency.name());
79		}
80	
